CREATE TABLE bot_threads (id INTEGER PRIMARY KEY, system_number TEXT NOT NULL, peer_number TEXT NOT NULL, flow_id INTEGER, started_at INTEGER NOT NULL, last_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE (system_number, peer_number));
CREATE INDEX idx_bot_threads_updates ON bot_threads(updated_at, id);
ALTER TABLE messages ADD COLUMN bot TEXT CHECK (bot IS NULL OR json_valid(bot));
INSERT INTO bot_threads (system_number,peer_number,flow_id,started_at,last_at,updated_at) SELECT p.system_number,p.peer_number,COALESCE((SELECT v.flow_id FROM conversations v WHERE v.system_number=p.system_number AND v.peer_number=p.peer_number),(SELECT a.flow_id FROM bot_answers a WHERE a.system_number=p.system_number AND a.peer_number=p.peer_number ORDER BY a.id DESC LIMIT 1)),MIN(p.at),COALESCE((SELECT MAX(m.occurred_at) FROM messages m WHERE m.system_number=p.system_number AND m.peer_number=p.peer_number),MAX(p.at)),COALESCE((SELECT MAX(m.occurred_at) FROM messages m WHERE m.system_number=p.system_number AND m.peer_number=p.peer_number),MAX(p.at)) FROM (SELECT system_number,peer_number,occurred_at AS at FROM messages WHERE sent_by='בוט' UNION ALL SELECT system_number,peer_number,started_at FROM conversations UNION ALL SELECT system_number,peer_number,at FROM bot_answers) p GROUP BY p.system_number,p.peer_number;
